package __PKG__;

import android.content.ContentValues;
import android.net.Uri;
import android.os.Build;
import android.os.Environment;
import android.provider.MediaStore;
import android.util.Base64;
import android.widget.Toast;
import com.getcapacitor.JSObject;
import com.getcapacitor.Plugin;
import com.getcapacitor.PluginCall;
import com.getcapacitor.PluginMethod;
import com.getcapacitor.annotation.CapacitorPlugin;
import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStream;

// Generated by Web to App Instant — saves files created in the web app
// (Blob / data: URLs) into the phone's Downloads folder.
@CapacitorPlugin(name = "WTADownloader")
public class WTADownloaderPlugin extends Plugin {

    @PluginMethod
    public void save(PluginCall call) {
        String data = call.getString("data", "");
        String name = call.getString("name", "download");
        String mime = call.getString("mime", "application/octet-stream");
        try {
            int comma = data.indexOf(',');
            byte[] bytes = Base64.decode(comma >= 0 ? data.substring(comma + 1) : data, Base64.DEFAULT);
            name = name.replaceAll("[\\\\/:*?\"<>|]", "_");
            if (name.isEmpty()) name = "download";
            if (Build.VERSION.SDK_INT >= 29) {
                ContentValues v = new ContentValues();
                v.put(MediaStore.MediaColumns.DISPLAY_NAME, name);
                v.put(MediaStore.MediaColumns.MIME_TYPE, mime);
                v.put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS);
                Uri uri = getContext().getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, v);
                if (uri == null) throw new Exception("Storage unavailable");
                try (OutputStream os = getContext().getContentResolver().openOutputStream(uri)) {
                    os.write(bytes);
                }
            } else {
                File dir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS);
                dir.mkdirs();
                try (FileOutputStream os = new FileOutputStream(new File(dir, name))) {
                    os.write(bytes);
                }
            }
            final String saved = name;
            getActivity().runOnUiThread(() -> Toast.makeText(getContext(), "Saved to Downloads: " + saved, Toast.LENGTH_LONG).show());
            JSObject ret = new JSObject();
            ret.put("name", name);
            call.resolve(ret);
        } catch (Exception e) {
            call.reject("Could not save file: " + e.getMessage());
        }
    }
}
